'use strict';
const puzzle=[
{id:'newton',name:'Isaac Newton',aliases:['newton','isaac newton','sir isaac newton'],subject:'SCIENCE',clue:'Whose laws explain motion, gravity, and that very famous falling apple?',field:0,nation:0},
{id:'prince',name:'Prince',aliases:['prince','prince rogers nelson'],subject:'MUSIC',clue:'Which one-name musician gave us “Purple Rain” and “When Doves Cry”?',field:2,nation:1},
{id:'hugo',name:'Victor Hugo',aliases:['hugo','victor hugo'],subject:'LITERATURE',clue:'Who wrote Les Misérables and The Hunchback of Notre-Dame?',field:1,nation:2},
{id:'pasteur',name:'Louis Pasteur',aliases:['pasteur','louis pasteur'],subject:'SCIENCE',clue:'Which scientist lends his name to the process that makes milk safer to drink?',field:0,nation:2},
{id:'austen',name:'Jane Austen',aliases:['austen','jane austen'],subject:'LITERATURE',clue:'Which novelist introduced us to Elizabeth Bennet and Mr. Darcy?',field:1,nation:0},
{id:'bowie',name:'David Bowie',aliases:['bowie','david bowie'],subject:'MUSIC',clue:'Which musician’s alter ego was the otherworldly Ziggy Stardust?',field:2,nation:0},
{id:'morrison',name:'Toni Morrison',aliases:['morrison','toni morrison'],subject:'LITERATURE',clue:'Who wrote Beloved and became the first Black woman to win the Nobel Prize in Literature?',field:1,nation:1},
{id:'debussy',name:'Claude Debussy',aliases:['debussy','claude debussy'],subject:'MUSIC',clue:'Which composer wrote the piano piece “Clair de lune” in Suite bergamasque?',field:2,nation:2},
{id:'feynman',name:'Richard Feynman',aliases:['feynman','richard feynman','richard p feynman'],subject:'SCIENCE',clue:'Which physicist gives his name to diagrams that track interactions between subatomic particles?',field:0,nation:1}
];
const labels={field:['Scientists','Writers','Musicians'],nation:['British','American','French']};
const KEY='two-truths-example-v1';
const fresh=()=>({solved:[],hints:{},revealed:[],phase:0,axis:null,groups:[],second:[],mistakes:0,clueMistakes:0});
let state=fresh();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.solved)&&[0,1,2,3].includes(saved.phase))state={...fresh(),...saved}}catch{}
let selected=[],notice='',order=puzzle.map(p=>p.id);
const $=s=>document.querySelector(s),game=$('#game');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function say(t){$('#announce').textContent=t}
function norm(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function setNotice(t){notice=t;render();say(t)}
function render(){save();for(let i=0;i<3;i++){const b=$('#step'+i);b.classList.toggle('active',i===(state.phase===0?0:state.phase===3?2:1));b.disabled=i===1&&state.solved.length<9||i===2&&state.phase!==3;b.setAttribute('aria-current',b.classList.contains('active')?'step':'false')}
if(state.phase===0)renderClues();else if(state.phase===3)renderResults();else renderGroups();}
function renderClues(){game.innerHTML=`<div class="section-head"><div><h2>Start with what you know.</h2><p class="sub">Solve the clues to collect your nine answers. Last names are welcome.</p></div><div class="progress"><span class="progress-dots">${puzzle.map(p=>`<i class="${state.solved.includes(p.id)?'on':''}"></i>`).join('')}</span>${state.solved.length} / 9 solved</div></div><div class="clue-grid">${puzzle.map((p,i)=>{const done=state.solved.includes(p.id),h=state.hints[p.id]||0;return `<article class="card ${done?'solved':''}"><div class="card-top"><span>${p.subject}</span><span class="${done?'check':''}">${done?'✓':String(i+1).padStart(2,'0')}</span></div><p class="question">${p.clue}</p>${done?`<p class="answer-name">${p.name}</p><span class="answer-note">${state.revealed.includes(p.id)?'Revealed · a new one to remember':'Nicely known.'}</span>`:`<form data-id="${p.id}"><div class="answerline"><input autocomplete="off" spellcheck="false" aria-label="Answer to clue ${i+1}" placeholder="${h?hintText(p,h):'Your answer…'}"><button aria-label="Submit answer to clue ${i+1}">↗</button></div><div class="card-feedback" role="status"></div></form><div class="card-tools"><button data-hint="${p.id}">Letter hint${h?' · '+h:''}</button><button data-reveal="${p.id}">Reveal</button></div>`}</article>`}).join('')}</div><div class="bottom-bar"><p>${state.solved.length===9?'Your nine answers are ready. What connects them?':'No rush. Every answer is part of two connections.'}</p><button class="primary" id="begin" ${state.solved.length===9?'':'disabled'}>Find the connections <span>↗</span></button></div>`;
game.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const p=puzzle.find(p=>p.id===f.dataset.id),value=f.querySelector('input').value;if(!value.trim())return; if(p.aliases.some(a=>norm(a)===norm(value))){state.solved.push(p.id);say(p.name+'. Correct.');render();const next=game.querySelector('input');if(next)next.focus()}else{state.clueMistakes++;save();f.querySelector('.card-feedback').textContent='Not quite. Try again, or take a hint.';say('Not quite. Try again.')}});
game.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>{const id=b.dataset.hint;state.hints[id]=Math.min((state.hints[id]||0)+1,puzzle.find(p=>p.id===id).name.replace(/ /g,'').length-1);render();const f=game.querySelector(`[data-id="${id}"] input`);f.focus();say('Letter hint: '+f.placeholder)});
game.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{state.solved.push(b.dataset.reveal);state.revealed.push(b.dataset.reveal);render();say('Answer revealed: '+puzzle.find(p=>p.id===b.dataset.reveal).name)});
$('#begin').onclick=()=>{state.phase=1;notice='';selected=[];render();game.scrollIntoView({behavior:'smooth',block:'start'})};}
function hintText(p,n){let count=0;return [...p.name].map(c=>c===' '?' ':++count<=n?c:'_').join(' ')}
function currentAxis(){return state.phase===1?state.axis:(state.axis==='field'?'nation':'field')}
function activeGroups(){return state.phase===1?state.groups:state.second}
function renderGroups(){const round=state.phase,groups=activeGroups(),axis=currentAxis(),used=groups.flatMap(g=>puzzle.filter(p=>p[axis]===g).map(p=>p.id)),available=order.filter(id=>!used.includes(id));game.innerHTML=`<div class="section-head"><div><span class="round-label">${round===1?'THE FIRST TRUTH':'THE SECOND TRUTH'}</span><h2>${round===1?'One set. One way of seeing.':'Same people. A different connection.'}</h2><p class="sub">${round===1?'Find three groups of three. The groups should all follow one lens.':'Find three new groups of three. Each trio uses one person from each original group.'}</p></div><div class="progress">${groups.length} / 3 groups found</div></div>${groups.map((g,i)=>`<div class="solved-group c${i}"><strong>${labels[axis][g]}</strong><p>${puzzle.filter(p=>p[axis]===g).map(p=>p.name).join(' · ')}</p></div>`).join('')}${groups.length<3?`${round===2?`<div class="round-info">Your first lens: ${state.axis==='field'?'what they do':'their nationality'}. Look for a different shared trait.<br>The small labels show your original groups.</div>`:''}<div class="tile-grid">${available.map(id=>{const p=puzzle.find(p=>p.id===id);return `<button class="tile ${selected.includes(id)?'selected':''}" data-tile="${id}" aria-pressed="${selected.includes(id)}">${p.name}${round===2?`<small>${labels[state.axis][p[state.axis]]}</small>`:''}</button>`}).join('')}</div><p class="message" role="status">${notice||'Select three answers that belong together.'}</p><div class="group-toolbar"><button class="secondary" id="shuffle">Shuffle ↺</button><button class="secondary" id="clear" ${selected.length?'':'disabled'}>Deselect</button><button class="primary" id="checkgroup" ${selected.length===3?'':'disabled'}>Check group${selected.length?' · '+selected.length+'/3':''}</button></div><div class="group-toolbar"><button class="quiet" id="groupHint">Need a nudge?</button></div>`:`<div class="round-complete"><h2>${round===1?'One truth found.':'Both truths, connected.'}</h2><p class="sub">${round===1?'Now turn your knowledge around. There’s another way to group every answer.':'A little perspective makes everything fit.'}</p><button class="primary" id="next" style="margin-top:22px">${round===1?'Find the second truth':'See the bigger picture'} <span>↗</span></button></div>`}`;
game.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{const id=b.dataset.tile;if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<3)selected.push(id);else{say('Three selected. Deselect a tile to choose another.');return}notice='';render();game.querySelector(`[data-tile="${id}"]`)?.focus()});
if($('#checkgroup'))$('#checkgroup').onclick=checkGroup;if($('#clear'))$('#clear').onclick=()=>{selected=[];notice='';render()};if($('#shuffle'))$('#shuffle').onclick=()=>{for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}render()};if($('#groupHint'))$('#groupHint').onclick=()=>{setNotice(axis==='field'?'Think about the work these people are known for.':axis==='nation'?'Think about where these people come from.':'One lens is their work. The other is where they come from.');};if($('#next'))$('#next').onclick=()=>{state.phase++;selected=[];notice='';render();game.scrollIntoView({behavior:'smooth',block:'start'})};}
function checkGroup(){if(selected.length!==3)return;const chosen=selected.map(id=>puzzle.find(p=>p.id===id));let axis=currentAxis();if(!axis)axis=['field','nation'].find(a=>chosen.every(p=>p[a]===chosen[0][a]));if(axis&&chosen.every(p=>p[axis]===chosen[0][axis])){if(state.phase===1&&!state.axis)state.axis=axis;activeGroups().push(chosen[0][axis]);selected=[];notice='A connection made.';say(labels[axis][chosen[0][axis]]+'. Group found.');render()}else{state.mistakes++;setNotice('Not this trio. Try a different connection.' );}}
function renderResults(){const hintCount=Object.values(state.hints).reduce((a,b)=>a+b,0);game.innerHTML=`<div class="result-intro"><div class="eyebrow">PUZZLE 001 · COMPLETE</div><h2>You saw it both ways.</h2><p class="sub">Nine people. Three callings. Three nationalities.<br>Here’s how the two truths meet.</p></div><div class="matrix" role="table" aria-label="People by profession and nationality"><span></span>${labels.nation.map(n=>`<div class="col-label" role="columnheader">${n}</div>`).join('')}${labels.field.map((f,i)=>`<div class="row-label" role="rowheader">${f}</div>${labels.nation.map((n,j)=>`<div class="matrix-cell row${i}" role="cell">${puzzle.find(p=>p.field===i&&p.nation===j).name}</div>`).join('')}`).join('')}</div><div class="learn"><div class="eyebrow">ONE MORE CONNECTION</div><p>Newton studied light as well as gravity; Debussy explored it through music in <i>Clair de lune</i> (“moonlight”). Very different work, a shared curiosity about the world.</p></div><div class="result-actions"><p class="stats">${9-state.revealed.length} answers recalled · ${hintCount} letter hints · ${state.mistakes} grouping ${state.mistakes===1?'miss':'misses'}</p><button class="primary" id="share">Copy my result <span>↗</span></button><p class="message" id="copyStatus" role="status">A spoiler-free little brag for the group chat.</p></div>`;$('#share').onclick=async()=>{const text=`Two Truths · Puzzle 001\n${'🟩'.repeat(3)} ${'🟪'.repeat(3)}\nBoth truths found!\n${9-state.revealed.length}/9 recalled · ${hintCount} letter hints · ${state.mistakes} grouping misses`;try{await navigator.clipboard.writeText(text);$('#copyStatus').textContent='Copied. Share your perspective.'}catch{$('#copyStatus').textContent=text;$('#copyStatus').style.whiteSpace='pre-line'} };}
$('#how').onclick=()=>$('#help').showModal();$('#help .close').onclick=()=>$('#help').close();$('.close-help').onclick=()=>$('#help').close();$('#restart').onclick=()=>$('#reset').showModal();$('#cancelreset').onclick=()=>$('#reset').close();$('#confirmreset').onclick=()=>{state=fresh();selected=[];notice='';order=puzzle.map(p=>p.id);$('#reset').close();render()};$('#step0').onclick=()=>{state.phase=0;render()};$('#step1').onclick=()=>{state.phase=state.second.length===3?2:state.groups.length===3?2:1;selected=[];notice='';render()};$('#step2').onclick=()=>{state.phase=3;render()};render();
